<?php require_once '../includes/auth.php'; require_role('distributor'); $page_title='Shops'; $uid=(int)$_SESSION['user_id']; if(isset($_POST['add'])){ $n=clean($conn,$_POST['name']); $e=clean($conn,$_POST['email']); $p=password_hash($_POST['password'],PASSWORD_DEFAULT); mysqli_query($conn,"INSERT INTO users(name,email,password,role,parent_id,status) VALUES('$n','$e','$p','shop',$uid,'active')"); $sid=mysqli_insert_id($conn); mysqli_query($conn,"INSERT INTO warehouses(name,location,owner_id,owner_role) VALUES('Main Shop Warehouse','Shop Location',$sid,'shop')"); log_audit($conn,$uid,'Create Shop',$e); redirect('shops.php'); } include '../includes/header.php'; include '../includes/sidebar.php'; $q=mysqli_query($conn,"SELECT * FROM users WHERE role='shop' AND parent_id=$uid"); ?><div class="row g-4"><div class="col-md-4"><div class="card-box"><h5>Add Shop</h5><form method="POST"><input class="form-control mb-2" name="name" placeholder="Shop Name"><input class="form-control mb-2" name="email" type="email" placeholder="Email"><input class="form-control mb-3" name="password" placeholder="Password"><button name="add" class="btn btn-success">Save</button></form></div></div><div class="col-md-8"><div class="card-box"><table class="table"><tr><th>Name</th><th>Email</th><th>Status</th></tr><?php while($r=mysqli_fetch_assoc($q)){ ?><tr><td><?php echo $r['name']; ?></td><td><?php echo $r['email']; ?></td><td><?php echo $r['status']; ?></td></tr><?php } ?></table></div></div></div><?php include '../includes/footer.php'; ?>
